package org.bars4j.encode.matrix.aztec;

import org.bars4j.encode.matrix.ecc.GfField;

/**
 * Arithmetic in the binary extension fields that Aztec error correction is built on.
 *
 * <p>ISO/IEC 24778 assigns one field GF(2^m) to each data codeword width m {@code = 6, 8, 10, 12},
 * plus GF(16) for the four-bit words of the mode message. Each field is generated by a primitive
 * polynomial; exponentiation by the primitive element is tabulated so that products become sums of
 * logarithms.
 *
 * <p>The arithmetic is delegated to the shared {@link GfField}; this class maps the Aztec codeword
 * widths onto their fields and keeps the package-private entry point the Aztec pipeline uses.
 */
final class AztecField {

    /** {@code x^4 + x + 1}, used for the 4-bit words of the mode message. */
    private static final GfField GF16 = GfField.of(0x13, 16);
    /** {@code x^6 + x + 1}, used for 6-bit data codewords. */
    private static final GfField GF64 = GfField.of(0x43, 64);
    /** {@code x^8 + x^5 + x^3 + x^2 + 1}, used for 8-bit data codewords. */
    private static final GfField GF256 = GfField.of(0x12D, 256);
    /** {@code x^10 + x^3 + 1}, used for 10-bit data codewords. */
    private static final GfField GF1024 = GfField.of(0x409, 1024);
    /** {@code x^12 + x^6 + x^5 + x^3 + 1}, used for 12-bit data codewords. */
    private static final GfField GF4096 = GfField.of(0x1069, 4096);

    private final GfField field;

    private AztecField(GfField field) {
        this.field = field;
    }

    /** Returns the field used for codewords of the given width. */
    static AztecField forWordSize(int wordSize) {
        switch (wordSize) {
            case 4:
                return new AztecField(GF16);
            case 6:
                return new AztecField(GF64);
            case 8:
                return new AztecField(GF256);
            case 10:
                return new AztecField(GF1024);
            case 12:
                return new AztecField(GF4096);
            default:
                throw new IllegalArgumentException("No Aztec field for a " + wordSize + "-bit codeword");
        }
    }

    /** Returns {@code alpha} raised to {@code exponent}, reduced modulo the multiplicative order. */
    int exp(int exponent) {
        return field.exp(exponent);
    }

    /** Returns the discrete logarithm of {@code value}, which must be non-zero. */
    int log(int value) {
        return field.log(value);
    }

    /** Multiplies two field elements. */
    int multiply(int a, int b) {
        return field.multiply(a, b);
    }

    /** The shared field this adapter delegates to. */
    GfField delegate() {
        return field;
    }
}
